"""Own bilingual whole material, supplied model data; no observed learners or trials."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
claim=Path('curricula/DE/Gymnasium/quality/goal-evidence/2026-10-12/chemie-current402-all182-open-claims-root-20261012-v2/claims/equilibrium-redox-kinetics-16.current402.claim.config.json')
IDS=json.loads(claim.read_text())['goalIds'];CASES=[];SPECS=[]
def spec(archetype,*phrases):
 assert len(phrases)==6;SPECS.append({'goalId':IDS[len(SPECS)],'archetype':archetype,'essentialPairs':[list(phrases[i:i+2]) for i in range(0,6,2)]})
def case(n,letter,title,matde,maten,taskde,tasken,solde,solen,trde,tren,*rubrics):
 assert len(rubrics)==6
 CASES.append({'id':f'eqrk16-{n:02d}-{letter}','goalId':IDS[n-1],'title':title,'provenance':'Own fictional teaching data/model, CC-BY-4.0. Not actual learner work, laboratory observations, official measurements, or current product specifications. Numerical constants are supplied teaching values under the stated conditions.','imageRequired':False,'materialsDe':matde,'materialsEn':maten,'taskDe':taskde,'taskEn':tasken,'workedReasoningDe':solde,'workedReasoningEn':solen,'freshIndependentTransferDe':trde,'freshIndependentTransferEn':tren,'criterionToObservableRubric':[{'criterionId':f'e{i+1}','observableDe':rubrics[2*i],'observableEn':rubrics[2*i+1],'points':4,'evidenceBoundary':'Future independent reasoning is not yet observed; solution text and a score alone never demonstrate mastery.'} for i in range(3)],'scoring':{'maximumPoints':12,'interpretation':'Four points per specific criterion: 4 complete justified performance; 3 correct with a minor omission; 2 partly correct relationship; 1 isolated relevant statement; 0 absent/incorrect. Score supports diagnosis and does not itself grant mastery.','criticalRequirement':'A correct calculation does not compensate for a missing chemical explanation or a false model/safety claim.'}})
spec('modeling','Löslichkeit folgt aus Aktivitäten und stöchiometrischen Exponenten, nicht allein aus dem Zahlenwert von KL.','Solubility follows activities and stoichiometric exponents, not the numerical Ksp alone.','Sättigung ist dynamisch; Q und KL unterscheiden einen Ausgangszustand vom Gleichgewicht.','Saturation is dynamic; Q and Ksp distinguish an initial state from equilibrium.','Gleichion und weitere gekoppelte Reaktionen verändern gelöste Stoffmengen bei festem KL.','Common ions and coupled reactions change dissolved amounts at fixed Ksp.')
case(1,'a','Unterschiedliche Stöchiometrie, keine Löslichkeitsrangfolge aus KL allein',
'25 °C; ideale verdünnte Lösungen, c°=1 mol/L. AgCl(s) ⇌ Ag+ + Cl−, KL=1,8·10−10; CaF2(s) ⇌ Ca2+ + 2 F−, KL=3,2·10−11. In reinem Wasser seien Hydrolyse und Komplexbildung vernachlässigbar. Beide Gefäße enthalten nach langer Zeit sichtbaren Feststoff. Datenaufgabe, kein Umgang mit Silber- oder Fluoridsalzen.',
'25 °C; ideal dilute solutions, c°=1 mol/L. AgCl(s) ⇌ Ag+ + Cl−, Ksp=1.8×10−10; CaF2(s) ⇌ Ca2+ + 2 F−, Ksp=3.2×10−11. In pure water neglect hydrolysis and complex formation. Both vessels retain visible solid after a long time. Data exercise, no handling of silver or fluoride salts.',
'Leite die beiden KL-Ausdrücke und molaren Löslichkeiten her. Prüfe die Behauptungen „kleineres KL bedeutet stets weniger gelöste Formeleinheiten“ und „sichtbarer Feststoff bedeutet, dass keine Teilchen mehr wechseln“. Begründe die verwendeten Näherungen.',
'Derive both Ksp expressions and molar solubilities. Assess “a smaller Ksp always means fewer dissolved formula units” and “visible solid means particles no longer exchange”. Justify your approximations.',
'AgCl: KL=(s/c°)^2, s=√(1,8·10−10)c°=1,34·10−5 mol/L. CaF2: KL=(s/c°)(2s/c°)^2=4(s/c°)^3, s=2,00·10−4 mol/L. Trotz kleinerem KL ist hier die molare Löslichkeit von CaF2 größer; unterschiedliche Stöchiometrie verhindert die pauschale Rangfolge. Im gesättigten System laufen Lösen und Kristallisieren mit gleicher mittlerer Rate weiter. KL beschreibt Aktivitäten; Konzentrationen sind nur unter der Idealnäherung passend, Feststoffaktivität ist eins.',
'AgCl: Ksp=(s/c°)^2, giving s=1.34×10−5 mol/L. CaF2: Ksp=4(s/c°)^3, giving s=2.00×10−4 mol/L. Despite its smaller Ksp, CaF2 has the greater molar solubility here; different stoichiometry defeats the blanket ranking. Dissolution and crystallisation continue at equal average rates in the saturated system. Ksp uses activities; concentrations apply only with the stated ideal approximation, and pure solid has unit activity.',
'Ein Salz M2X liefert 2 M+ und X2−. Stelle seinen Ausdruck selbst auf und entscheide, ob der AgCl-Wurzelansatz zulässig ist. Prüfe anschließend, was fehlender Feststoff über Sättigung tatsächlich aussagt.',
'A salt M2X yields 2 M+ and X2−. Construct its expression and decide whether the AgCl square-root method applies. Then explain what the absence of solid actually tells you about saturation.',
'Exponenten aus Auflösungsgleichungen ableiten.','Derive exponents from dissolution stoichiometry.','1,34·10−5 und2,00·10−4 mol/L einschließlich Rangfolgengegenbeispiel herleiten.','Derive both solubilities and the counterexample to simple Ksp ranking.','Dynamischen Teilchenaustausch und Konzentrationsnäherung erklären.','Explain dynamic particle exchange and the concentration approximation.')
case(1,'b','Gleichion und Fällungsentscheidung nach dem Mischen',
'25 °C; AgCl-KL=1,8·10−10, c°=1 mol/L. Je 50,0 mL AgNO3 (2,0·10−5 mol/L) und NaCl (2,0·10−5 mol/L) werden im Gedankenexperiment gemischt; Volumina additiv. Ein zweites gesättigtes AgCl-System steht mit 0,0100 mol/L NaCl und überschüssigem Feststoff in Kontakt. Keine weiteren Reaktionen, verdünnt-ideal.',
'At 25 °C, AgCl Ksp=1.8×10−10 and c°=1 mol/L. Mix 50.0 mL each of 2.0×10−5 mol/L AgNO3 and NaCl in a thought experiment; volumes add. A second saturated AgCl system contains 0.0100 mol/L NaCl and excess solid. No other reactions; dilute-ideal model.',
'Berechne Q unmittelbar nach dem Mischen und entscheide über eine Fällung. Berechne im zweiten System die Gleichgewichtskonzentration von Ag+ und erläutere, warum Zugabe von NaCl KL nicht verkleinert. Stelle die Wirkung von Ammoniak als neuer Komplexbildner qualitativ gegenüber, ohne Zahlen zu erfinden.',
'Calculate Q immediately after mixing and decide whether precipitation occurs. Calculate equilibrium Ag+ in the second system and explain why adding NaCl does not reduce Ksp. Contrast ammonia as a new complexing agent qualitatively without inventing constants.',
'Nach Verdünnung jeweils1,0·10−5 mol/L, daher Q=1,0·10−10<KL: keine thermodynamisch erforderliche Fällung, Lösung ungesättigt. Im NaCl-System [Ag+]≈KL c°²/[Cl−]=1,8·10−8 mol/L; zusätzliches Chlorid unterdrückt das Lösen, KL bleibt bei gleicher Temperatur gleich. Ammoniak bindet freies Ag+ zu einem Komplex; der gekoppelte Verbrauch freier Ionen kann mehr Feststoff lösen. Gesamtsilber und freies Ag+ sind dann verschieden; quantitative Aussagen brauchen Komplexkonstante und Bilanz.',
'After dilution each concentration is 1.0×10−5 mol/L, hence Q=1.0×10−10<Ksp: precipitation is not thermodynamically required and the solution is unsaturated. With NaCl, [Ag+]≈1.8×10−8 mol/L. Extra chloride suppresses dissolution; Ksp at the same temperature is unchanged. Ammonia binds free Ag+ in a complex and can drive further dissolution. Total silver differs from free Ag+; quantitative conclusions need formation constants and balances.',
'Eine dritte Probe wird zehnfach mit Wasser verdünnt. Unterscheide ein Gefäß mit überschüssigem AgCl von einer zuvor abfiltrierten gesättigten Lösung: Wo kann durch weiteres Lösen wieder Sättigung entstehen?',
'Dilute a third sample tenfold with water. Contrast excess solid AgCl with a previously filtered saturated solution: where can further dissolution restore saturation?',
'Verdünnung vor Q-Vergleich berücksichtigen.','Include dilution before comparing Q with Ksp.','Gleichionwirkung quantitativ erklären, ohne KL-Änderung zu behaupten.','Quantify the common-ion effect without changing Ksp.','Freie Ionenkonzentration, Gesamtgehalt und Komplexkopplung trennen.','Distinguish free ions, total concentration, and complex coupling.')
spec('investigation','Elektronenübertragung und Wärmebilanz beschreiben denselben Redoxumsatz auf verschiedenen Ebenen.','Electron transfer and the heat balance describe the same redox conversion at different levels.','Kalorimetrische Temperaturänderung wird erst mit Systemgrenze, Wärmekapazität und Stoffumsatz zu Reaktionswärme.','A temperature change yields reaction heat only with a system boundary, heat capacity, and conversion.','Messverluste und Nebenprozesse begrenzen Enthalpieaussagen; Aktivierungsenergie ist keine Reaktionswärme.','Heat losses and side processes limit enthalpy claims; activation energy is not reaction heat.')
case(2,'a','Zink verdrängt Kupfer: Thermometrie planen und auswerten',
'Bereitgestellte Modellmessung:20,0mL0,200mol/L CuSO4, Zinküberschuss; Flüssigkeit20,0g, c=4,18J/(gK), Gefäßwärmekapazität15,0J/K. Temperatur vor Zugabe20,0°C, auf Zugabezeit rückextrapolierter Wert29,0°C; Auflösung±0,1K je Temperatur. Vollständiger Cu2+-Umsatz wird für die Rechnung angenommen. Praktischer Zukunftspfad nur im beaufsichtigten Schullabor: Lehrkraft gibt geprüftes Kleinstmengenprotokoll frei; Schutzbrille, Rührer und Temperatursonde, kein Anfassen der Suspension; kupferhaltige Abfälle getrennt, kein Ausguss. Keine Heimdurchführung.',
'Supplied model measurement:20.0mL0.200mol/L CuSO4, excess zinc; liquid20.0g, c=4.18J/(gK), vessel heat capacity15.0J/K. Temperature before addition20.0°C and back-extrapolated to mixing29.0°C; resolution±0.1K for each temperature. Assume complete Cu2+ conversion for the calculation. A future practical route requires a supervised school laboratory and a teacher-approved microscale protocol: goggles, stirrer, probe, no touching the suspension; collect copper-containing waste, never drain disposal. No home experiment.',
'Erzeuge Teil- und Gesamtgleichung, Donator/Akzeptor und einen Stoff-zu-Teilchen-Bezug. Plane Messfolge, Leerwert und Kontrollbedingungen für einen eigenen zukünftigen Versuch. Berechne Wärme und molare Reaktionsenthalpie im Modell, erläutere Vorzeichen und mindestens zwei Grenzen. Die bereitgestellten Daten ersetzen keine eigene Durchführung.',
'Construct half/overall equations, donor/acceptor roles, and an observation-to-particle link. Plan a measurement sequence, blank, and controls for a future investigation. Calculate heat and molar reaction enthalpy in the model; explain signs and at least two limitations. Supplied data do not demonstrate your own conduct.',
'Zn→Zn2++2e−; Cu2++2e−→Cu; gesamt Zn+Cu2+→Zn2++Cu. Zink ist Elektronendonator, Cu2+ Akzeptor; Kupferabscheidung und abnehmende blaue Färbung wären passende, aber getrennt zu protokollierende Beobachtungen. n=0,00400mol; C=20,0·4,18+15,0=98,6J/K; qUmgebung=+887,4J, qReaktion≈−887,4J, ΔrH≈−222kJ/mol Umsatz. Bei gleichem Anfangszustand vor/nach Zugabe regelmäßig T und Zeit, Rühren und Isolation protokollieren; Leerwert mit Lösung ohne reagierendes Zink prüft Drift/Mischwärme. Wärmeverlust, Metallwärmekapazität, unvollständige Reaktion und Extrapolation begrenzen die Näherung; Auflösungsgrenze für ΔT konservativ±0,2K ergibt etwa±2,2% nur für diesen Anteil. Exothermie sagt nichts über die Höhe der Aktivierungsbarriere.',
'Zn→Zn2++2e−; Cu2++2e−→Cu; overall Zn+Cu2+→Zn2++Cu. Zinc donates electrons and Cu2+ accepts them; copper deposition and fading blue colour would be relevant observations requiring a separate record. n=0.00400mol; C=98.6J/K; surroundings gain887.4J, reaction releases about887.4J, giving ΔrH≈−222kJ/mol conversion. Record T/time regularly before/after mixing under controlled stirring/insulation; a nonreacting solution blank tests drift/mixing heat. Heat loss, metal heat capacity, incomplete conversion and extrapolation limit the estimate. Conservative resolution±0.2K in ΔT corresponds to about±2.2% for this contribution alone. Exothermicity does not specify the activation barrier.',
'Ein elektrisch belastetes galvanisches System setzt dieselbe Redoxreaktion räumlich getrennt um. Erkläre, warum gemessene Wärme allein dort nicht dieselbe gesamte Energieübertragung erfasst, und ergänze die notwendige elektrische Messung.',
'A loaded galvanic cell spatially separates the same redox reaction. Explain why heat alone no longer measures all energy transfer and specify the electrical measurements needed.',
'Bilanzierte Elektronenübertragung mit Donator/Akzeptor zuordnen.','Assign donor/acceptor roles using balanced electron transfer.','Messplan und887J/−222kJmol−1 mit Systemvorzeichen erzeugen.','Produce a controlled measurement plan and the heat/enthalpy with signs.','Eigene Durchführung, Modellmessung, Unsicherheit und Aktivierungsbarriere abgrenzen.','Separate own conduct, model data, uncertainty, and activation barrier.')
case(2,'b','Wärmeverlust und andere Akzeptorstufe',
'Datenmodell einer bereits vorbereiteten sauren Lösung:Zn+2Fe3+→Zn2++2Fe2+; Fe3+ im Überschuss, umgesetztes Zn0,00500mol. Gesamte effektive Wärmekapazität229J/K. Isoliertes Modellgerät: ΔT4,00K; weniger isoliertes Gerät: ΔT3,10K. Gleiche Anfangstemperatur/Stoffmengen. Zusätzlich angegebener Herstellertext:„Die niedrigere Temperatur beweist kleinere chemische Energie der Reaktion.“ Keine Schülerzubereitung saurer Metallsalzlösungen.',
'Data model of a pre-prepared acidic solution:Zn+2Fe3+→Zn2++2Fe2+; excess Fe3+, converted Zn0.00500mol. Effective total heat capacity229J/K. Insulated model apparatus:ΔT4.00K; less insulated:ΔT3.10K. Initial temperatures and quantities are identical. Supplier claim:“The lower temperature proves a smaller chemical energy of reaction.” Students do not prepare acidic metal-salt solutions.',
'Leite Teilgleichungen und Elektronenbilanz selbst ab. Vergleiche beide scheinbaren molaren Wärmen und prüfe die Herstellerbehauptung. Entwirf eine unabhängige Kontrolle, die Wärmeverlust von unvollständigem Umsatz trennt. Begründe, warum Fe3+ hier Akzeptor ist, obwohl metallisches Eisen in anderen Zellen Donator sein kann.',
'Derive half-reactions and electron balance. Compare the two apparent molar heats and assess the supplier claim. Design an independent control distinguishing heat loss from incomplete conversion. Explain why Fe3+ accepts electrons here although iron metal can donate electrons elsewhere.',
'Zn→Zn2++2e− und2Fe3++2e−→2Fe2+. q=916J bzw709,9J; scheinbare molare Werte−183,2 bzw−142,0kJ/molZn. Unterschiedliche Isolation verändert Wärmeabgabe an ungemessene Umgebung; sie beweist keinen anderen Reaktionszustandsunterschied. Temperatur-Zeit-Kurven, Kalibrierung und unabhängige Bestimmung des verbliebenen Zn oder gebildeten Fe2+ würden Wärmeverlust/Umsatz auseinanderhalten. Rollen gehören zu konkreten Redoxpaaren und Zuständen: Fe3+ wird reduziert; Fe0 kann zuFe2+ oxidieren. Keine Gleichsetzung der Werte mit Aktivierungsenergien oder einer isolierten Elektronenenergie.',
'Zn→Zn2++2e− and2Fe3++2e−→2Fe2+. Heat is916J versus709.9J, giving apparent−183.2 versus−142.0kJ/molZn. Insulation changes heat loss into unmeasured surroundings; it does not establish a different reaction state-function change. Temperature/time curves, calibration, and independent measurement of remaining Zn or produced Fe2+ distinguish heat loss from conversion. Roles refer to particular couples/states:Fe3+ is reduced; Fe0 can be oxidised toFe2+. Neither value is an activation energy or isolated “electron energy”.',
'Bei konstantem Volumen ohne elektrische Arbeit wird Qv gemessen. Erläutere, welche zusätzliche Annahme eine Bezeichnung als ΔH erfordern würde, statt Qv automatisch gleichzusetzen.',
'At fixed volume without electrical work Qv is measured. Explain which additional assumption is needed before labelling it ΔH rather than automatically equating them.',
'Fe3+/Fe2+ und Zn/Zn2+ statt pauschaler Elementrollen verwenden.','Use actual redox couples rather than fixed elemental roles.','Beide scheinbaren molaren Wärmen auf gleichen Umsatz beziehen.','Compare apparent molar heats on the same conversion basis.','Kontrolle zur Trennung von Wärmeverlust und Stoffumsatz entwerfen.','Design a control separating heat loss from conversion.')
spec('concept','Korrosion ist eine räumlich gekoppelte Oxidation und Reduktion mit elektronischer und ionischer Verbindung.','Corrosion couples spatially separated oxidation/reduction through electronic and ionic paths.','Opferanoden schützen durch bevorzugte Oxidation und kathodische Polarisation, Beschichtungen durch Barrierewirkung.','Sacrificial anodes protect by preferential oxidation/cathodic polarisation; coatings act as barriers.','Werkstoffpaarung, Sauerstoff und Beschichtungsdefekte verändern den lokalen Angriff, ohne dass Standardpotenziale die Rate allein festlegen.','Material pairing, oxygen and coating defects change local attack; standard potentials alone do not determine its rate.')
case(3,'a','Beschädigte Zink- und Zinnschicht auf Stahl',
'Belüftetes neutrales Salzwasser; Schicht und Stahl sind elektrisch verbunden. Tabelle Standard-Reduktionspotenziale als qualitative Hilfe:Zn2+/Zn−0,76V; Fe2+/Fe−0,44V; Sn2+/Sn−0,14V. FallA Zinküberzug mit kleiner Schramme; FallB Zinnüberzug mit gleich großer Schramme. Löslicher Sauerstoff kann an kathodischen Stellen reduziert werden. Datenmodell; keine Salzwasserversuche mit Schwermetallabfällen zu Hause.',
'Aerated neutral saline water; coating and steel are electrically connected. Standard reduction potentials as a qualitative aid:Zn2+/Zn−0.76V; Fe2+/Fe−0.44V; Sn2+/Sn−0.14V. A:zinc coating with a small scratch; B:tin coating with the same scratch. Dissolved oxygen can be reduced at cathodic sites. Data model, no home heavy-metal corrosion experiment.',
'Erkläre beide Lokalelemente mit Teilgleichungen und Elektronen-/Ionenwegen. Entscheide, welche Schicht auch nach Verletzung Opferwirkung besitzt. Begründe einen möglichen Flächeneffekt und die Grenzen einer allein aus E° berechneten Korrosionsprognose.',
'Explain both local cells with half-reactions and electron/ion paths. Decide which coating retains sacrificial protection after damage. Discuss a possible area effect and limitations of predicting corrosion solely from E°.',
'Zink:Zn→Zn2++2e−; Elektronen gelangen durch Metall zum Stahl, dortO2+2H2O+4e−→4OH−. Stahl wird kathodisch geschützt, solange der Zinkkontakt und Elektrolytleitweg bestehen. Bei Zinn ist freigelegtes Eisen die bevorzugte Anode:Fe→Fe2++2e−, Sauerstoffreduktion an edlerer Zinnfläche. Große Kathodenfläche bei kleiner Eisenanode kann den lokalen Angriff verstärken; konkrete Rate benötigt Polarisation, Transport, Passivierung und Geometrie. Ionenwanderung im Wasser erhält Ladungsbilanz; Elektronen laufen nicht als freie Elektronen durch die Salzlösung. Rostbildung umfasst weitere Hydroxid-/Oxidationsschritte, nicht bloß Fe→Fe2+.',
'With zinc:Zn→Zn2++2e−; electrons pass through metal to steel, whereO2+2H2O+4e−→4OH− occurs. Steel is cathodically protected while metallic/electrolytic paths remain. With tin, exposed iron is the preferred anode:Fe→Fe2++2e−, with oxygen reduction on nobler tin. A large cathode with a small iron anode can intensify local attack; actual rate also requires polarisation, transport, passivation and geometry. Ionic motion maintains charge balance in water; free electrons do not travel through the salt solution. Rust formation includes further hydroxide/oxidation chemistry.',
'Ersetze belüftetes neutrales Wasser durch sauerstoffarmes saures Medium. Welche kathodische Teilreaktion kann nun wichtig werden, und welche frühere Sauerstoffbegründung muss neu geprüft werden?',
'Replace aerated neutral water with oxygen-poor acidic solution. Which cathodic half-reaction can become important and which oxygen-based explanation must be reconsidered?',
'Beide Lokalelemente mit korrektem Sauerstoffreduktionsweg erklären.','Explain both local cells with balanced oxygen reduction.','Barrierewirkung, Opferwirkung und Defektflächen vergleichen.','Compare barrier protection, sacrificial action and defect areas.','Thermodynamische Richtung von unbekannter Korrosionsrate trennen.','Separate thermodynamic tendency from unknown corrosion rate.')
case(3,'b','Opferanode ohne Kontakt und Belüftungselement',
'Modell eines Stahlbehälters im leitfähigen Wasser. A:angeschraubte Zinkanode mit blankem Metallkontakt; B:gleiche Zinkanode an isolierendem Nylonhalter ohne Kabel. Ein Wassertropfen auf ungeschütztem Stahl besitzt sauerstoffreichen Rand und sauerstoffarmen Mittelpunkt. Lokale Messidee:Potentiale mit Referenzelektrode, Materialabtrag und Sauerstoffverteilung; noch keine Messwerte.',
'Model steel tank in conducting water. A:zinc anode bolted with clean metal contact; B:same zinc on an insulating nylon holder without a wire. A droplet on unprotected steel has an oxygen-rich rim and oxygen-poor centre. Proposed local measurements:reference-electrode potentials, material loss and oxygen distribution; no measurements have yet been made.',
'Begründe Schutz oder fehlenden Schutz inA/B und leite Anoden-/Kathodenorte im Belüftungselement ab. Plane eine überprüfbare Wartungsentscheidung einschließlich Anodenverbrauch und Kontrollen; erfinde keine gemessene Schutzwirkung. Ist „mehr Sauerstoff bedeutet an jedem Ort mehr Eisenauflösung“ tragfähig?',
'Explain protection or its absence inA/B and locate anodic/cathodic sites in the differential-aeration cell. Plan a testable maintenance decision including anode consumption and controls; do not invent measured protection. Assess “more oxygen means more iron dissolution at every location”.',
'A ermöglicht einen äußeren metallischen Elektronenweg; Zink oxidiert bevorzugt. InB fehlt dieser Weg, daher schützt allein das benachbarte Zink den Tank nicht verlässlich. Am sauerstoffreichen Rand wird die kathodische Sauerstoffreduktion begünstigt, im sauerstoffärmeren Zentrum kann Eisen anodisch aufgelöst werden; gekoppelte Orte widerlegen die einfache Ortsregel. Wartung prüft Kontakt, verbleibende Masse/Geometrie, Elektrolytleitfähigkeit und Potential unter definierten Bedingungen; Austausch vor Verbrauch. Abtrag und Potentialmessung mit/ohne Kontakt und ohne Zink bei kontrolliertem Sauerstoff erlauben eine reale Prüfung. Passivierung und örtliche Strömung können die Situation ändern; keine Erfolgsbehauptung aus dem Plan.',
'A supplies a metallic electron path and zinc preferentially oxidises. B lacks that path; adjacent zinc alone does not reliably protect the tank. Oxygen reduction is favoured at the oxygen-rich rim while iron can dissolve anodically in the oxygen-poor centre; coupled sites defeat the simple location rule. Maintenance checks contact, remaining mass/geometry, conductivity and potential under defined conditions; replace before depletion. Controlled loss/potential comparisons with/without contact and without zinc can test actual protection. Passivation/flow may change the outcome; a plan is not a successful trial.',
'Eine Gleichstromquelle ersetzt die Zinkanode durch eine Fremdstromanlage. Begründe benötigte Polung am Stahl und warum sich der Wartungsbefund „Zinkverbrauch“ nicht einfach überträgt.',
'An external DC supply replaces the sacrificial zinc system. Justify the steel polarity and explain why the zinc-consumption maintenance rule no longer transfers directly.',
'Metallischen und elektrolytischen Kreis als Schutzbedingung zeigen.','Identify metallic and electrolytic paths as protection conditions.','Differenzbelüftung mit getrennten lokalen Reaktionsorten begründen.','Explain differential aeration through separate reaction sites.','Überprüfbaren Wartungsplan ohne erfundene Daten entwickeln.','Develop a testable maintenance plan without invented results.')
